UPDATE group_config
SET user_blacklist = #{userBlacklistJson}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

UPDATE group_config
SET allowed_member_task_categories = #{allowedMemberJson},
    allowed_autonomous_categories  = #{allowedAutonomousJson}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

UPDATE group_config
SET transcript_retain_policy = #{policy}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
